package au.aumanet.app;
import java.util.*;import java.security.PublicKey;import org.json.JSONObject;
/** Fresh authenticated control reply, not an RF measurement timestamp. */
final class GatewayRadioSignal {
 static final long PERIOD=5000,WINDOW=5000;final String node,peer,group,owner,relay;final long epoch;final PublicKey key;final int role;
 private GatewayBootCodec.Message pending,accepted;private long began,next,observed,readAnchor;private String run="";
 GatewayRadioSignal(String node,String peer,String group,long epoch,String owner,String relay,PublicKey key,int role){this.node=node;this.peer=peer;this.group=group;this.epoch=epoch;this.owner=owner;this.relay=relay;this.key=key;this.role=role;}
 synchronized GatewayBootCodec.Message begin(String verifiedRun,String nonce,long now,java.util.function.BooleanSupplier live){if(!live.getAsBoolean()||verifiedRun==null||verifiedRun.isEmpty())return null;if(!run.equals(verifiedRun)){pending=null;accepted=null;next=0;run=verifiedRun;}if(now<next)return null;pending=GatewayBootCodec.signalQuery(node,group,epoch,owner,relay,nonce);began=now;next=now+PERIOD;return pending;}
 synchronized void receive(GatewayBootCodec.Frame frame,String verifiedRun,java.util.function.LongSupplier clock,java.util.function.BooleanSupplier live)throws Exception{long now=clock.getAsLong();GatewayBootCodec.Message p=pending,m=frame.message;if(p==null||m.kind!='H'||!live.getAsBoolean()||now<began||now-began>=WINDOW||!run.equals(verifiedRun)||!m.run.equals(run)||!GatewayBootCodec.sameCommon(p,m)||!m.signalPeer.equals(peer)||m.signalRole!=role)return;if(!frame.verify(key))return;now=clock.getAsLong();if(pending!=p||!live.getAsBoolean()||now<began||now-began>=WINDOW||!run.equals(verifiedRun))return;pending=null;accepted=m;observed=now;readAnchor=began;}
 synchronized JSONObject snapshot(String verifiedRun,long now,long revision,boolean live)throws Exception{GatewayBootCodec.Message m=accepted;if(!live||m==null||!run.equals(verifiedRun)||now<observed)return null;long age=m.signalReadAge+now-readAnchor;if(age<0||age>GroupNamePolicy.MAX_REVISION)return null;JSONObject result=new JSONObject().put("status",m.signalStatus==0?"available":m.signalStatus==1?"unsupported":"unavailable").put("authenticated",true).put("verification","pinned-node").put("receiverNodeId",node).put("transmitterNodeId",peer).put("sourceRun",run).put("observationId",m.challenge).put("kind","associated-ap-last-known").put("direction",role==1?"ap-to-station":"station-to-ap").put("readAgeMs",age).put("sampleAgeKnown",false).put("observedElapsedMs",now).put("configRevision",revision);if(m.signalStatus==0)result.put("rssiDbm",m.signalRssi);return result;}
}
